INSERT INTO ref.vault_registry_meta (singleton, registry, version, as_of, sha256, notice) VALUES (true, 'vetbuddy.benefit_vault_registry', '1.0.0', '2026-10-27', 'c8fb4d6c2ea24098947cbbe82e5b7d494f22e4af7392bb342981a08964218035', 'VetBuddy is an independent information and organization platform, not VA, DoD or a government agency. Its benefit matches, career suggestions and form assistance are recommendations based on the information you provide and identified sources. They are not the law, an official eligibility or rating decision, medical advice, a diagnosis, a medical nexus opinion, legal representation or a guarantee of approval. The responsible agency determines eligibility and benefits. Verify current requirements with the administering agency and, for VA claims assistance, a currently VA-accredited representative, claims agent or attorney. Check any separate professional license with the appropriate state authority.')
