  ('wy.overseas-combat-veteran-tuition', 'WY', 'EDU', 'STATE_BENEFIT', 'Overseas combat veteran tuition', ARRAY['vet','sp','ch']::TEXT[], 'res & ((vet & hon) | ((dep | ss) & (spkia | sppm)))', ARRAY['dep','hon','res','spkia','sppm','ss','vet']::TEXT[], 'Resident honorably discharged veterans with an expeditionary or campaign medal; eligible spouses and children', 'Tuition at community colleges or UW for eight semesters within eight years', 'https://communitycolleges.wy.edu/veteran-tuition-benifit', 'LINKED_FROM_SOURCE', 'src.d1126f9772a6a0f5', 2, 'UNVERIFIED', '2868276fb6336f23c7477546952648698ef759b03d805671427be9bcc85e5722', 'states/batch07_WV-NM.psv:77', 'c8fb4d6c2ea24098947cbbe82e5b7d494f22e4af7392bb342981a08964218035'),
