  ('wy.resident-prices-for-nonresident-members-stationed-in-wyoming', 'WY', 'HUNTFISH', 'STATE_BENEFIT', 'Resident prices for nonresident members stationed in Wyoming', ARRAY['ad']::TEXT[], 'nonres & ad & stn', ARRAY['ad','nonres','stn']::TEXT[], 'Nonresident active duty stationed in Wyoming 90+ days', 'Resident-price hunting and fishing licenses', 'https://www.wyomilitary.wyo.gov/wp-content/uploads/2024/04/VetsBenefitBook_April2024.pdf', 'LINKED_FROM_SOURCE', 'src.d1126f9772a6a0f5', 2, 'UNVERIFIED', '1078d6cab0dc752540fca258cacbff7e57aef3f4ccb3f3534ecd77d87c477bc4', 'states/batch07_WV-NM.psv:73', 'c8fb4d6c2ea24098947cbbe82e5b7d494f22e4af7392bb342981a08964218035'),
  ('wy.state-employment-veterans-preference', 'WY', 'JOBS', 'STATE_BENEFIT', 'State employment veterans'' preference', ARRAY['vet','dv','ss']::TEXT[], 'res & ((vet & hon) | ss)', ARRAY['hon','res','ss','vet']::TEXT[], 'Residents of 1+ year: honorably discharged veterans, disabled veterans and surviving spouses', '5% scoring preference; 10% for disabled veterans', 'https://law.justia.com/codes/wyoming/title-19/chapter-14/section-19-14-102/', 'LINKED_FROM_SOURCE', 'src.d1126f9772a6a0f5', 2, 'UNVERIFIED', '1d88993bf73ff57267c9ad3b8a8b104d71108d3f2e6171ca76afac7a6bf5270e', 'states/batch07_WV-NM.psv:79', 'c8fb4d6c2ea24098947cbbe82e5b7d494f22e4af7392bb342981a08964218035'),
  ('wy.state-sponsored-life-insurance', 'WY', 'GUARD_PAY', 'STATE_BENEFIT', 'State Sponsored Life Insurance', ARRAY['ng','sp','ch']::TEXT[], 'ng', ARRAY['ng']::TEXT[], 'Wyoming Guard members, spouses and children', '$1,000 free; new recruits $10,000 free for the first year', 'https://wynga.org/insurance/', 'LINKED_FROM_SOURCE', 'src.d1126f9772a6a0f5', 2, 'UNVERIFIED', 'd26ef4dde728f3986446eb5aa34a5167632d91f8d5332cb98e9a742e5020ba38', 'states/batch07_WV-NM.psv:83', 'c8fb4d6c2ea24098947cbbe82e5b7d494f22e4af7392bb342981a08964218035'),
  ('wy.tuition-for-survivors-and-dependents-of-guard-members', 'WY', 'EDU', 'STATE_BENEFIT', 'Tuition for survivors and dependents of Guard members', ARRAY['sp','ch','ss']::TEXT[], '(dep | ss) & (spkia | spsc)', ARRAY['dep','spkia','spsc','ss']::TEXT[], 'Spouse or children of a Guard member who died or was permanently disabled on state duty', 'Tuition and fees at Wyoming colleges and trade schools', 'https://law.justia.com/codes/wyoming/title-19/chapter-9/article-4/section-19-9-403/', 'LINKED_FROM_SOURCE', 'src.d1126f9772a6a0f5', 2, 'UNVERIFIED', '84731e566118188bcca25aa494555e8c8456e4b9a2dc87ef88e47f5a12fec672', 'states/batch07_WV-NM.psv:78', 'c8fb4d6c2ea24098947cbbe82e5b7d494f22e4af7392bb342981a08964218035'),
  ('wy.veterans-home-of-wyoming', 'WY', 'HOMES', 'STATE_BENEFIT', 'Veterans Home of Wyoming', ARRAY['vet','sp','ss']::TEXT[], 'res & ((vet & hon) | sp | ss)', ARRAY['hon','res','sp','ss','vet']::TEXT[], 'Residents of 1+ year with an honorable discharge, and eligible dependents', 'Assisted living and skilled nursing; fees based on ability to pay', 'https://health.wyo.gov/aging/veteranshome/', 'LINKED_FROM_SOURCE', 'src.d1126f9772a6a0f5', 2, 'UNVERIFIED', '01c1e4fdbf87bed8d46b1c1f8ac3b31c4039c7407625d44511680a96c55f6659', 'states/batch07_WV-NM.psv:84', 'c8fb4d6c2ea24098947cbbe82e5b7d494f22e4af7392bb342981a08964218035'),
  ('wy.veterans-property-tax-exemption', 'WY', 'PROPTAX', 'STATE_BENEFIT', 'Veterans property tax exemption', ARRAY['vet','dv','ss']::TEXT[], 'res & (vet | ss)', ARRAY['res','ss','vet']::TEXT[], 'Residents of 3+ years with an honorable discharge and qualifying service or disability; surviving spouses', '$6,000 off the assessed value of the primary residence', 'https://wyo-prop-div.wyo.gov/tax-relief', 'LINKED_FROM_SOURCE', 'src.d1126f9772a6a0f5', 2, 'UNVERIFIED', '7fffc1b2a5dc7e6061d53b5831bd1584a2e9910a912a5deb40673b01351c989c', 'states/batch07_WV-NM.psv:65', 'c8fb4d6c2ea24098947cbbe82e5b7d494f22e4af7392bb342981a08964218035'),
  ('wy.wyoming-national-guard-educational-assistance-plan', 'WY', 'GUARD_EDU', 'STATE_BENEFIT', 'Wyoming National Guard Educational Assistance Plan', ARRAY['ng']::TEXT[], 'ng', ARRAY['ng']::TEXT[], 'Guard members past basic training or OCS, in good standing, with a 2.0 GPA', '100% of resident tuition and fees at Wyoming colleges; private schools up to $1,500 a semester', 'https://veteranseducation.wyo.gov/state-tuition-assistance/Welcome-page', 'LINKED_FROM_SOURCE', 'src.d1126f9772a6a0f5', 2, 'UNVERIFIED', 'fcfdd0a48ca474e36333112394f41b2581cf7b6a9f44eaa4cb3782a9cde2a5c7', 'states/batch07_WV-NM.psv:75', 'c8fb4d6c2ea24098947cbbe82e5b7d494f22e4af7392bb342981a08964218035'),
  ('wy.wyoming-national-guard-referral-incentive', 'WY', 'BONUS', 'STATE_BENEFIT', 'Wyoming National Guard referral incentive', ARRAY['ng']::TEXT[], 'ng', ARRAY['ng']::TEXT[], 'Guard members whose referral leads to an enlistment', '$500 per enlistment', 'https://www.wyomilitary.wyo.gov/resources/state/state-benefits/', 'LINKED_FROM_SOURCE', 'src.d1126f9772a6a0f5', 2, 'UNVERIFIED', 'b24fc4ed4eea5a4123b48fc0b806a31135cd243409d1b36fde5ce62718e1cd76', 'states/batch07_WV-NM.psv:81', 'c8fb4d6c2ea24098947cbbe82e5b7d494f22e4af7392bb342981a08964218035')
INSERT INTO ref.vault_rule_lead (lead_id, topic, citation, lead, caveat, record_status, registry_sha256) VALUES
  ('gr.army_ca', 'Army Credentialing Assistance', 'AR 621-5; ALARACT 102/2025', 'Funds credentials that need not align to the MOS but must retain a military nexus. Since 19 Mar 2026 every TA and CA request needs supervisor or commander approval in ArmyIgnitED.', 'Officer restriction inferred from an agency summary, not the ALARACT itself.', 'UNVERIFIED', 'c8fb4d6c2ea24098947cbbe82e5b7d494f22e4af7392bb342981a08964218035'),
  ('gr.ch1606', 'Montgomery GI Bill — Selected Reserve', '10 USC 16132', 'Requires SELRES status and a six-year obligation entered on or after 1 Jul 1985 plus a secondary-school credential. Not vested: ends on transfer out of SELRES (IRR/ING), with tuition-recoupment exposure mid-course.', NULL, 'SOURCE_CHECKED', 'c8fb4d6c2ea24098947cbbe82e5b7d494f22e4af7392bb342981a08964218035'),
  ('gr.ch33', 'Post-9/11 GI Bill', '38 USC 3301', '90 cumulative qualifying days since 11 Sep 2001 meets the eligibility threshold; percentage tier scales with total time. Drill, annual training and State Active Duty do not count.', 'At 85–89 days, orders can sometimes be extended before they expire, almost never after (March 2020 Guard activations were extended for this reason).', 'SOURCE_CHECKED', 'c8fb4d6c2ea24098947cbbe82e5b7d494f22e4af7392bb342981a08964218035'),
  ('gr.dod_civilian', 'DoD civilian scope', '5 USC; DoDI 1400.25; 5 USC 2108', 'Civilian employment does not create veteran status or veterans'' preference. A civilian who is also Guard/Reserve is assessed under the military status. Coast Guard permanent civilians are documented as TA-eligible; do not extend by analogy.', NULL, 'SOURCE_CHECKED', 'c8fb4d6c2ea24098947cbbe82e5b7d494f22e4af7392bb342981a08964218035'),
  ('gr.fta', 'Federal Tuition Assistance', '10 USC 2007; DoDI 1322.25; AR 621-5', '$4,500 per fiscal year, $250 per semester hour, 18 semester hours; master''s $350 per credit hour up to 39 (Army figures). Coast Guard SELRES: $4,500 / $250, one master''s only.', 'FTA pays first; schools deduct it before billing VA. Coast Guard figures rest on a secondary source (confirm COMDTINST). Re-verify FY27 rates after 1 Oct.', 'SOURCE_CHECKED', 'c8fb4d6c2ea24098947cbbe82e5b7d494f22e4af7392bb342981a08964218035'),
  ('gr.n426_180_day', '180-day minimum service for N-426 certification', 'Samma v. DoD; service implementing messages', 'SUPERSEDED. The requirement no longer exists; certification needs only an honest assessment that service has been honorable, and the first O-6 in the chain must process it within 30 days.', NULL, 'SUPERSEDED', 'c8fb4d6c2ea24098947cbbe82e5b7d494f22e4af7392bb342981a08964218035'),
  ('gr.naturalization', 'Naturalization during hostilities', 'INA 329; 8 USC 1440; USCIS Policy Manual vol. 12 pt. I ch. 3', 'Selected Reserve membership during a designated period of hostilities (11 Sep 2001 to present, open) is qualifying service; no activation, deployment or minimum period required. IRR/ING do not qualify on this path.', NULL, 'SOURCE_CHECKED', 'c8fb4d6c2ea24098947cbbe82e5b7d494f22e4af7392bb342981a08964218035'),
  ('gr.rudisill', 'Dual entitlement (Rudisill)', '38 USC 3695(a); Rudisill v. McDonough (2024)', 'Entitlements from separate service periods may be used in any order up to the 48-month aggregate cap with no forced election (held for Ch. 30 and Ch. 33).', 'Extension to a Ch. 1606 + Ch. 33 pairing is reasoning by analogy, not holding; Perkins (No. 24-6515, Vet. App.) may bear on it.', 'CONTESTED', 'c8fb4d6c2ea24098947cbbe82e5b7d494f22e4af7392bb342981a08964218035'),
  ('gr.state_definition_trap', 'State veteran status (structural)', 'State codes', 'Most state benefits key off a state-law definition of veteran requiring federal active duty. Guard service of only drill, annual training and State Active Duty often fails it (Texas Hazlewood needs 181 days).', NULL, 'SOURCE_CHECKED', 'c8fb4d6c2ea24098947cbbe82e5b7d494f22e4af7392bb342981a08964218035')
INSERT INTO ref.vault_benefit_lead (benefit_id, lead_id) VALUES ('us.army-tuition-assistance-armyignited', 'gr.army_ca'), ('us.army-tuition-assistance-armyignited', 'gr.fta'), ('us.extra-entitlement-for-two-or-more-service-periods-rudisill', 'gr.rudisill'), ('us.military-tuition-assistance', 'gr.fta'), ('us.montgomery-gi-bill-selected-reserve-chapter-1606', 'gr.ch1606'), ('us.post-9-11-gi-bill-chapter-33', 'gr.ch33');
INSERT INTO ref.vault_caveat (caveat_id, text, registry_sha256) VALUES
  ('army_approval_lead', 'Unchecked lead: since March 19, 2026 Army Tuition Assistance and Credentialing Assistance requests may need supervisor or commander approval in ArmyIgnitED. Confirm with your education center.', 'c8fb4d6c2ea24098947cbbe82e5b7d494f22e4af7392bb342981a08964218035'),
  ('commercial', 'This is a company''s offer, not a government benefit. Offers change often; confirm the current terms on the company''s page. VetBuddy does not endorse any company.', 'c8fb4d6c2ea24098947cbbe82e5b7d494f22e4af7392bb342981a08964218035'),
  ('guard_post911', 'For Guard and Reserve members, drills, annual training and State Active Duty do not count toward the Post-9/11 GI Bill; qualifying federal active duty does.', 'c8fb4d6c2ea24098947cbbe82e5b7d494f22e4af7392bb342981a08964218035'),
  ('mode_a_dropped', 'Some answers were not used because a guest search holds only basic facts. A private account can use rating, discharge and award answers.', 'c8fb4d6c2ea24098947cbbe82e5b7d494f22e4af7392bb342981a08964218035'),
  ('nonprofit', 'A private organization runs this program, not the government. Confirm the current terms with the organization.', 'c8fb4d6c2ea24098947cbbe82e5b7d494f22e4af7392bb342981a08964218035'),
  ('not_verified', 'No reviewer has checked this record yet. Read the official page before relying on it.', 'c8fb4d6c2ea24098947cbbe82e5b7d494f22e4af7392bb342981a08964218035'),
  ('recovered_lead', 'This lead came from an earlier VetBuddy dataset, not from a page read for the vault. Treat it as a pointer only.', 'c8fb4d6c2ea24098947cbbe82e5b7d494f22e4af7392bb342981a08964218035'),
  ('rudisill_contested', 'The 48-month rule for two service periods was decided for the Montgomery and Post-9/11 GI Bills. Whether it reaches the Selected Reserve GI Bill (Chapter 1606) is contested.', 'c8fb4d6c2ea24098947cbbe82e5b7d494f22e4af7392bb342981a08964218035'),
  ('seen_in_search', 'VetBuddy saw this link in search results but could not read the page, so the description may be incomplete.', 'c8fb4d6c2ea24098947cbbe82e5b7d494f22e4af7392bb342981a08964218035'),
  ('stale', 'The source page was last read more than the review period ago and may have changed.', 'c8fb4d6c2ea24098947cbbe82e5b7d494f22e4af7392bb342981a08964218035'),
  ('state_definition_trap', 'Many state benefits use the state''s own definition of a veteran, which often requires federal active duty. Guard or Reserve service of only drills, annual training or State Active Duty may not meet it (Texas Hazlewood, for example, needs 181 days). Check with the state veterans agency.', 'c8fb4d6c2ea24098947cbbe82e5b7d494f22e4af7392bb342981a08964218035'),
  ('superseded', 'This rule was replaced. It is shown only so you can see what changed.', 'c8fb4d6c2ea24098947cbbe82e5b7d494f22e4af7392bb342981a08964218035'),
  ('tail_unread', 'Part of the source page was not read, so other benefits from this state or territory may be missing.', 'c8fb4d6c2ea24098947cbbe82e5b7d494f22e4af7392bb342981a08964218035'),
  ('uncertain_facts', 'This depends on answers you marked as unsure. Your documents, such as a DD 214 or a VA rating letter, settle them.', 'c8fb4d6c2ea24098947cbbe82e5b7d494f22e4af7392bb342981a08964218035')
