INSERT INTO ref.vault_agent_manifest (agent_id, name, plane, role, may_issue_determinations, may_pull_from_agents, highest_class_held, registry_sha256) VALUES
  ('benefit_vault_agent', 'Benefit Vault', 5, 'Searches and matches benefits and deals and explains what the encoded rules say. Pulls facts from other agents only through the broker, with the person''s grant.', false, true, 'V2', 'c8fb4d6c2ea24098947cbbe82e5b7d494f22e4af7392bb342981a08964218035'),
  ('claims_navigator_agent', 'Claims Navigator', 3, 'Explains claim steps and points to accredited representatives. Holds condition details (V4); exposes nothing.', false, false, 'V4', 'c8fb4d6c2ea24098947cbbe82e5b7d494f22e4af7392bb342981a08964218035'),
  ('coverage_bridge_agent', 'Coverage Bridge (migration 0013)', 2, 'Holds checklist progress, resume drafts and the family packet. Nothing a vault rule reads.', false, false, 'V2', 'c8fb4d6c2ea24098947cbbe82e5b7d494f22e4af7392bb342981a08964218035'),
  ('crisis_support_agent', 'Crisis Support', 3, 'Shows the crisis floor. Holds nothing a vault rule may read (V5); exposes nothing.', false, false, 'V5', 'c8fb4d6c2ea24098947cbbe82e5b7d494f22e4af7392bb342981a08964218035'),
  ('household_agent', 'Household', 2, 'Holds family relationships for the family information packet.', false, false, 'V2', 'c8fb4d6c2ea24098947cbbe82e5b7d494f22e4af7392bb342981a08964218035'),
  ('service_profile_agent', 'Service Profile', 2, 'Holds the service history the person entered.', false, false, 'V2', 'c8fb4d6c2ea24098947cbbe82e5b7d494f22e4af7392bb342981a08964218035'),
  ('va_status_agent', 'VA Status', 2, 'Holds the rating facts the person copied from their VA letter. It also holds conditions, which are V4 and never leave it.', false, false, 'V4', 'c8fb4d6c2ea24098947cbbe82e5b7d494f22e4af7392bb342981a08964218035')
